// Assembles the self-contained neural noise suppression worklets from src/audio/worklets/parts/.
//
// AudioWorklet modules are loaded with audioWorklet.addModule(new URL(..., import.meta.url)), which
// Vite copies as plain assets, so a worklet cannot import anything: the shared parts and, for
// DeepFilterNet3, the wasm-bindgen glue are inlined here. Run `npm run build:worklets` after
// changing a part or rebuilding the glue, and commit the generated files.
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const client = dirname(dirname(fileURLToPath(import.meta.url)));
const worklets = join(client, 'src', 'audio', 'worklets');
const parts = join(worklets, 'parts');
const glueFile = join(client, 'src', 'audio', 'neural', 'deepfilternet3-glue.js');

const read = (name) => readFileSync(join(parts, name), 'utf8');
const banner = (what) => `// Generated by scripts/build-worklets.mjs: ${what}. Edit the parts, not this file.\n`;

/** The shared parts are ES modules (so tests can import them); inline them without the exports. */
const inline = (source) => source.replace(/^export (class|function|const|let|var) /gm, '$1 ');

/** wasm-bindgen --target web output, made self-contained: no ES exports and no URL-based async init. */
const adaptGlue = (source) => {
  let glue = source;
  const start = glue.indexOf('async function __wbg_init(');
  const end = glue.indexOf('export {', start);
  if (start >= 0 && end > start) glue = glue.slice(0, start) + glue.slice(end);
  glue = glue.replace(/^export \{[^}]*\};?\s*$/gm, '');
  glue = glue.replace(/^export (class|function|const|let|var) /gm, '$1 ');
  if (/^\s*import\b/m.test(glue) || /\bexport\b/.test(glue)) throw new Error('the glue still has imports or exports');
  return glue;
};

const deepfilter = [
  banner('DeepFilterNet3 worklet (global-scope shims, libDF wasm-bindgen glue, shared parts, processor)'),
  read('worklet-shims.js'),
  adaptGlue(readFileSync(glueFile, 'utf8')),
  inline(read('common.js')),
  read('deepfilter-processor.js'),
].join('\n');
writeFileSync(join(worklets, 'deepfilter-processor.js'), deepfilter);
console.log('wrote deepfilter-processor.js', deepfilter.length, 'bytes');

const rnnoise = [banner('RNNoise worklet (shared parts, processor)'), inline(read('common.js')), read('rnnoise-processor.js')].join('\n');
writeFileSync(join(worklets, 'rnnoise-processor.js'), rnnoise);
console.log('wrote rnnoise-processor.js', rnnoise.length, 'bytes');
